import fs from 'node:fs';
const path='de-at/eventfotografie/index.html';
const title='C-Level Eventfotografie | Wien–Budapest | BANHALMI';
const encoded=title.replace(/&/g,'&amp;');
let html=fs.readFileSync(path,'utf8');
const titleRe=/<title>[^<]*<\/title>/;
const ogRe=/<meta\b(?=[^>]*property="og:title")[^>]*\/?\s*>/;
const twRe=/<meta\b(?=[^>]*name="twitter:title")[^>]*\/?\s*>/;
if((html.match(new RegExp(titleRe.source,'g'))||[]).length!==1) throw new Error('unexpected title count');
html=html.replace(titleRe,`<title>${encoded}</title>`);
if(ogRe.test(html)) html=html.replace(ogRe,`<meta content="${encoded}" property="og:title"/>`); else html=html.replace('</title>',`</title><meta content="${encoded}" property="og:title"/>`);
if(twRe.test(html)) html=html.replace(twRe,`<meta name="twitter:title" content="${encoded}">`); else html=html.replace('</title>',`</title><meta name="twitter:title" content="${encoded}">`);
fs.writeFileSync(path,html);
for(const s of [`<title>${encoded}</title>`,`content="${encoded}" property="og:title"`,`name="twitter:title" content="${encoded}"`]) if(!html.includes(s)) throw new Error(`missing ${s}`);
console.log('Canonical German event page aligned to Wien–Budapest.');
